/**
 * @brief Constructor for ToyEventDisplay class
 * 
 * Initializes the display with a reference to a TPad and a GeomDataSource object
 * 
 * @param pad Reference to the TPad object
 * @param gds Constant reference to the GeomDataSource object
 * This comment was generated by meta-llama/Llama-3.3-70B-Instruct:None at temperature 0.01.
*/ 
ToyEventDisplay::ToyEventDisplay(TPad& pad, const WCP::GeomDataSource& gds)
    : pad(pad)
    , gds_flag(0)
    , gds(&gds)
    , dgds(0)
    , h1(0)
    , h2(0)
    , g1(0)
    , g2(0)
{
  recon_threshold = 1500;
  truth_threshold = 2000;
}

/**
 * @brief Constructor for ToyEventDisplay class
 * 
 * Initializes the object with the specified pad and detector geometry description
 * 
 * @param pad Reference to the TPad object
 * @param gds Constant reference to the DetectorGDS object
 * This comment was generated by meta-llama/Llama-3.3-70B-Instruct:None at temperature 0.01.
*/ 
ToyEventDisplay::ToyEventDisplay(TPad& pad, const WCP::DetectorGDS& gds)
    : pad(pad)
    , gds_flag(1)
    , gds(0)
    , dgds(&gds)
    , h1(0)
    , h2(0)
    , g1(0)
    , g2(0)
{
  recon_threshold = 1500;
  truth_threshold = 2000;
}

/**
 * Destructor for the class, releases any allocated resources.
 * This comment was generated by meta-llama/Llama-3.3-70B-Instruct:None at temperature 0.01.
*/ 
ToyEventDisplay::~ToyEventDisplay()
{
    this->clear();
}
/**
 * @brief Clears the event display by deallocating associated resources.
 *
 * Deletes previously allocated objects to free up memory and prevent leaks.
 * This comment was generated by meta-llama/Llama-3.3-70B-Instruct:None at temperature 0.01.
*/ 
void ToyEventDisplay::clear()
{
    if (h1) {
      delete h1;
    }
    if (h2) {
      delete h2;
    }
    if (g1) {
      delete g1;
    }
    if (g2) { 
      delete g2;
    }
}

/**
 * Initializes the event display with specified boundaries.
 *
 * @param x_min Minimum value of the X axis.
 * @param x_max Maximum value of the X axis.
 * @param y_min Minimum value of the Y axis.
 * @param y_max Maximum value of the Y axis.
 * @return Initialization status.
 * This comment was generated by meta-llama/Llama-3.3-70B-Instruct:None at temperature 0.01.
*/ 
int ToyEventDisplay::init(float x_min, float x_max, float y_min, float y_max)
{
  this->clear();

  h1 = new TH2F("h1","h1",1000,x_min,x_max,1000,y_min,y_max);
  if (gds_flag == 0){
    h1->SetTitle("Wires and True Hits ");
  }else{
    h1->SetTitle("Wires and True Hits (B face +x)");
  }
  h1->GetYaxis()->SetNdivisions(506);
  h1->GetXaxis()->SetNdivisions(506);
  h1->SetXTitle("Z (m)");
  h1->SetYTitle("Y (m)");
  h1->SetBinContent(0,0,1);
  h1->GetZaxis()->SetRangeUser(charge_min,charge_max);

  if (gds_flag == 1){
    h2 = new TH2F("h2","h2",1000,x_min,x_max,1000,y_min,y_max);
    h2->SetTitle("Wires and True Hits (A face -x)");
    h2->GetYaxis()->SetNdivisions(506);
    h2->GetXaxis()->SetNdivisions(506);
    h2->SetXTitle("Z (m)");
    h2->SetYTitle("Y (m)");
    h2->SetBinContent(0,0,1);
    h2->GetZaxis()->SetRangeUser(charge_min,charge_max);
  }

  return 0;
}

/**
 * @brief Draws Monte Carlo truth information on the event display.
 *
 * @param flag        Flag indicating the drawing mode (1, 2, or 3).
 * @param mctruth     Vector of point values containing Monte Carlo truth information.
 * @param option      Drawing option string.
 *
 * @return Integer value indicating success (0).
 * This comment was generated by meta-llama/Llama-3.3-70B-Instruct:None at temperature 0.01.
*/ 
int ToyEventDisplay::draw_mc(int flag, const WCP::PointValueVector& mctruth, TString option)
{
  if (gds_flag == 0 ){
    pad.cd();

    if (flag==1){
      h1->Draw(option);
      
    }else if (flag==2){
      h1->Reset();
      for (int i=0;i!=mctruth.size();i++){
	h1->Fill(mctruth[i].first.z/units::m,mctruth[i].first.y/units::m-0.02,int(mctruth[i].second*10)/10.);
      }
      h1->Draw(option);
    }else if (flag==3){
      //if (g1) delete g1;
      g1 = new TGraph();
      for (int i=0;i!=mctruth.size();i++){
	g1->SetPoint(i,mctruth[i].first.z/units::m,mctruth[i].first.y/units::m);
      }
      g1->SetMarkerColor(2);
      g1->SetMarkerSize(0.6);
      g1->Draw(option);
      g1->SetMarkerStyle(20);
    }
  }else{
    pad.cd(1);
    h1->Draw(option);
    
    pad.cd(2);
    h2->Draw(option);
  }
  
  return 0;
}


/**
 * @brief Draws bad cells on the display.
 *
 * This function takes a selection of geometric cells as input and draws them 
 * on the display. Each cell is represented by a polygonal line where the 
 * coordinates of the vertices are calculated from the boundary points of 
 * the cell.
 *
 * @param cells A reference to the selection of geometric cells to draw.
 * This comment was generated by meta-llama/Llama-3.3-70B-Instruct:None at temperature 0.01.
*/ 
void ToyEventDisplay::draw_bad_cell(WCP::GeomCellSelection& cells){
  pad.cd();
  for (int i=0;i!=cells.size();i++){
    double x[100];
    double y[100];
    
    for (int j=0;j!=cells.at(i)->boundary().size();j++){
      x[j] = cells.at(i)->boundary().at(j).z/units::m;
      y[j] = cells.at(i)->boundary().at(j).y/units::m;
      //std::cout << x[j] << " " << y[j] << std::endl;
    }
    x[cells.at(i)->boundary().size()] = x[0];
    y[cells.at(i)->boundary().size()] = y[0];
    // std::cout << x[4] << " " << y[4] << std::endl;
    // std::cout << std::endl;

    TPolyLine *pline = new TPolyLine(cells.at(i)->boundary().size()+1,x,y);
    pline->SetFillColor(5);
    pline->SetLineColor(5);
    //pline->SetLineWidth(1);
    pline->Draw("fsame");
    pline->Draw("same");
  }
}

/**
 * @brief Draws bad regions on the event display.
 *
 * This function takes a ChirpMap object, time, scale, plane, and option as input.
 * It iterates over the ChirpMap and draws lines representing wires 
 * that fall within the specified time range and plane.
 *
 * @param[in] chirpmap The ChirpMap object containing wire information.
 * @param[in] time The time at which to draw the bad regions.
 * @param[in] scale The scale factor for the time.
 * @param[in] plane The plane on which to draw the bad regions.
 * @param[in] option The drawing option.
 * This comment was generated by meta-llama/Llama-3.3-70B-Instruct:None at temperature 0.01.
*/ 
void ToyEventDisplay::draw_bad_region(WCP::ChirpMap& chirpmap, int time, int scale, int plane, TString option){
  pad.cd();

  // int nwire_u = gds->wires_in_plane(WirePlaneType_t(0)).size();
  // int nwire_v = gds->wires_in_plane(WirePlaneType_t(1)).size();
  // int nwire_w = gds->wires_in_plane(WirePlaneType_t(2)).size();
  
  //  std::cout << chirpmap.size() << std::endl;

  for (auto it = chirpmap.begin(); it!=chirpmap.end(); it++){
    if (time >= it->second.first/scale && time <= it->second.second/scale){
      const WCP::GeomWire *wire = gds->by_planeindex(WCP::WirePlaneType_t(plane),it->first);
      float pitch = gds->pitch(wire->plane());
      float angle = gds->angle(wire->plane());
      TLine *l3 = new TLine(wire->point1().z/units::m  ,wire->point1().y/units::m,
			    wire->point2().z/units::m  ,wire->point2().y/units::m);
      l3->SetLineColor(5);
      l3->Draw(option);
    }
  }

}


/**
 * @brief Draws merged wires on a display.
 *
 * This function takes a selection of geometric wires, an option string, 
 * and a color integer as input. It iterates over the selected wires, 
 * extracts the first and last wire from each merge, creates TLine objects 
 * representing these wires, sets their line color and style, and draws them 
 * according to the specified option.
 *
 * @param wires A selection of geometric wires to draw.
 * @param option An option string controlling the drawing behavior.
 * @param color An integer specifying the line color.
 * @return An integer indicating the result of the operation.
 * This comment was generated by meta-llama/Llama-3.3-70B-Instruct:None at temperature 0.01.
*/ 
int ToyEventDisplay::draw_merged_wires(WCP::GeomWireSelection wires, TString option, int color){
   for (int j=0;j!=wires.size();j++){
      
     WCP::MergeGeomWire *wire = (WCP::MergeGeomWire*)wires.at(j);
     const WCP::GeomWire *wire1 = wire->get_allwire().front();
     const WCP::GeomWire *wire2 = wire->get_allwire().back();
          
      TLine *l3 = new TLine(wire1->point1().z/units::m  ,wire1->point1().y/units::m,
      			    wire1->point2().z/units::m  ,wire1->point2().y/units::m);
      l3->SetLineColor(color);
      l3->Draw(option);
      l3->SetLineStyle(1);

      TLine *l1 = new TLine(wire2->point1().z/units::m  ,wire2->point1().y/units::m,
      			    wire2->point2().z/units::m  ,wire2->point2().y/units::m);
      l1->SetLineColor(color);
      l1->Draw(option);
      l1->SetLineStyle(1);
    }
    
    // break;
    



  
  return 0;
}

/**
 * @brief Draws wires on the event display.
 *
 * This function takes a selection of geometric wires and an option string as input,
 * and draws the wires on the event display. It calculates the pitch and angle of each wire,
 * creates TLine objects to represent the wires, and sets their line styles and colors.
 *
 * @param wires A reference to a GeomWireSelection object containing the wires to draw.
 * @param option A TString object specifying the drawing options.
 * @return An integer value indicating the success of the operation.
 * This comment was generated by meta-llama/Llama-3.3-70B-Instruct:None at temperature 0.01.
*/ 
int ToyEventDisplay::draw_wires(WCP::GeomWireSelection& wires, TString option){
  
 
    for (int j=0;j!=wires.size();j++){
      
      const WCP::GeomWire *wire = wires.at(j);
      
      
      
       float pitch = gds->pitch(wire->plane());
      float angle = gds->angle(wire->plane());
      //std::cout << pitch/units::mm << " " << angle << std::endl;
      
      TLine *l1 = new TLine(wire->point1().z/units::m - pitch/2./units::m/std::cos(angle/units::radian) ,wire->point1().y/units::m,
			    wire->point2().z/units::m - pitch/2./units::m/std::cos(angle/units::radian) ,wire->point2().y/units::m);
      l1->Draw(option);
      l1->SetLineStyle(1);
      
      TLine *l2 = new TLine(wire->point1().z/units::m + pitch/2./units::m/std::cos(angle/units::radian) ,wire->point1().y/units::m,
			    wire->point2().z/units::m + pitch/2./units::m/std::cos(angle/units::radian) ,wire->point2().y/units::m);
      l2->Draw(option);
      l2->SetLineStyle(1);
      
      TLine *l3 = new TLine(wire->point1().z/units::m  ,wire->point1().y/units::m,
			    wire->point2().z/units::m  ,wire->point2().y/units::m);
      l3->SetLineColor(2);
      l3->Draw(option);
      l3->SetLineStyle(1);
    }
    
    // break;
    



  
  return 0;
}

