/**
 * @brief Draws points on a graph.
 *
 * @param pcells Vector of points to draw.
 * @param option Drawing option.
 * @param color Color of the points.
 * This comment was generated by meta-llama/Llama-3.3-70B-Instruct:None at temperature 0.01.
*/ 
int ToyEventDisplay::draw_points(WCP::PointVector pcells, TString option, int color){
  TGraph *g1 = new TGraph();
  for (int i=0; i!=pcells.size(); i++){
    g1->SetPoint(i,pcells.at(i).z/units::m, pcells.at(i).y/units::m);
  }
  g1->Draw(option);
  g1->SetMarkerColor(color);
  g1->SetMarkerSize(1.0);
  g1->SetMarkerStyle(20);
}


/**
 * @brief Draws cells on a display based on the provided selection and options.
 *
 * @param cellall Selection of geometric cells to draw.
 * @param option Drawing option string.
 * @param color Color to use for drawing.
 * @return Integer value indicating success or failure.
 * This comment was generated by meta-llama/Llama-3.3-70B-Instruct:None at temperature 0.01.
*/ 
int ToyEventDisplay::draw_cells(const WCP::GeomCellSelection& cellall, TString option, int color)
{
  if (gds_flag == 1){
    g2 = new TGraph();
    g2b = new TGraph();
    int nf = 0;
    int nb = 0;
    for (int i=0;i!=cellall.size();i++){
      if (cellall[i]->get_face()==1){
	g2->SetPoint(nf,cellall[i]->center().z/units::m,cellall[i]->center().y/units::m);
	nf ++;
      }else{
	g2b->SetPoint(nb,cellall[i]->center().z/units::m,cellall[i]->center().y/units::m);
	nb ++;
      }
    }
    pad.cd(1);
    g2->SetMarkerColor(color);
    g2->SetMarkerSize(0.8);
    g2->Draw(option);
    g2->SetMarkerStyle(21);

    pad.cd(2);
    g2b->SetMarkerColor(color);
    g2b->SetMarkerSize(0.8);
    if (g2b->GetN()!=0)
      g2b->Draw(option);
    g2b->SetMarkerStyle(21);
  }else{
    pad.cd();
    
    //if (g2) delete g2;
    g2 = new TGraph();
    for (int i=0;i!=cellall.size();i++){
      g2->SetPoint(i,cellall[i]->center().z/units::m,cellall[i]->center().y/units::m);
    }
    g2->SetMarkerColor(color);
    g2->SetMarkerSize(0.8);
    g2->Draw(option);
    g2->SetMarkerStyle(21);
  }
  return 0;
}


/**
 * @brief Draws merged cells on a display.
 *
 * This function takes a selection of geometric cells, an option string, and a flag integer,
 * and draws the merged cells according to the specified options and flag value.
 *
 * @param cellall A selection of geometric cells to draw.
 * @param option A string specifying drawing options.
 * @param flag An integer flag controlling drawing behavior.
 * @return An integer indicating success or failure.
 * This comment was generated by meta-llama/Llama-3.3-70B-Instruct:None at temperature 0.01.
*/ 
int ToyEventDisplay::draw_mergecells(const WCP::GeomCellSelection& cellall, TString option, int flag)
{
 
  
  int np = 0;
  int npb = 0;
  g2 = new TGraph();
  g2b = new TGraph();
  
  for (int i=0;i!=cellall.size();i++){
    const WCP::MergeGeomCell* mcell = (const WCP::MergeGeomCell*)cellall.at(i);
    int face = mcell->get_allcell().at(0)->get_face();

    if (flag==0){
      
      if (face == 1){
	g2->SetPoint(np,cellall[i]->center().z/units::m,cellall[i]->center().y/units::m);
	//std::cout << cellall[i]->center().z/units::m << " " << cellall[i]->center().y/units::m << std::endl;
	np++;
      }else{
	g2b->SetPoint(npb,cellall[i]->center().z/units::m,cellall[i]->center().y/units::m);
	//std::cout << cellall[i]->center().z/units::m << " " << cellall[i]->center().y/units::m << std::endl;
	npb++;
      }
    }else if (flag==1){
      WCP::MergeGeomCell *mcell = (WCP::MergeGeomCell*)cellall[i];
      if (mcell->GetContainTruthCell()){
	if (face == 1){
	  g2->SetPoint(np,cellall[i]->center().z/units::m,cellall[i]->center().y/units::m);
	  np++;
	}else{
	  g2b->SetPoint(npb,cellall[i]->center().z/units::m,cellall[i]->center().y/units::m);
	  npb++;
	}
      }
    }
  }

  
  pad.cd(1);
  g2->SetMarkerColor(2);
  g2->SetMarkerSize(0.8);
  if (g2->GetN()!=0)
    g2->Draw(option);
  g2->SetMarkerStyle(24);
  
  pad.cd(2);
  g2b->SetMarkerColor(2);
  g2b->SetMarkerSize(0.8);
  if (g2b->GetN()!=0)
    g2b->Draw(option);
  g2b->SetMarkerStyle(24);

  return 0;
}



/**
 * @brief Draws truth cells based on the provided cell charge map and display options.
 *
 * This function iterates over the cell charge map, filters out cells based on their face and charge values,
 * and plots the corresponding points on a graph. The plotting behavior varies depending on the value of gds_flag.
 *
 * @param ccmap Cell charge map containing point-cell pairs with associated charges.
 * @param option Display option string influencing the drawing process.
 * @return Integer indicating successful completion of the drawing operation.
 * This comment was generated by meta-llama/Llama-3.3-70B-Instruct:None at temperature 0.01.
*/ 
int ToyEventDisplay::draw_truthcells(const WCP::CellChargeMap& ccmap, TString option)
{
  if (gds_flag==1){
    g2 = new TGraph();
    g2b = new TGraph();
    int nf = 0;
    int nb = 0;
    
    int i=0;
    for (auto it = ccmap.begin();it!=ccmap.end(); it++){
      WCP::Point p = it->first->center();
      if (it->first->get_face()==1){
	if (it->second > truth_threshold){
	  g2->SetPoint(nf,p.z/units::m,p.y/units::m);
	  nf++;
	}
      }else{
	if (it->second > truth_threshold){
	  g2b->SetPoint(nb,p.z/units::m,p.y/units::m);
	  nb++;
	}
      }
      
    }
    pad.cd(1);
    g2->SetMarkerColor(8);
    //g2->SetMarkerColor(1);
    g2->SetMarkerSize(0.8);
    g2->Draw(option);
    g2->SetMarkerStyle(26);

    pad.cd(2);
    g2b->SetMarkerColor(8);
    //g2->SetMarkerColor(1);
    g2b->SetMarkerSize(0.8);
    if (g2b->GetN()!=0)
      g2b->Draw(option);
    g2b->SetMarkerStyle(26);

  }else{
    pad.cd();
    
    g2 = new TGraph();
    int i=0;
    for (auto it = ccmap.begin();it!=ccmap.end(); it++){
      WCP::Point p = it->first->center();
      if (it->second > truth_threshold){
	g2->SetPoint(i,p.z/units::m,p.y/units::m);
	i++;
      }
    }
    g2->SetMarkerColor(8);
    //g2->SetMarkerColor(1);
    g2->SetMarkerSize(0.8);
    g2->Draw(option);
    g2->SetMarkerStyle(26);
  }
  
  return 0;
}

/**
 * @brief Draws truth cells charge on a pad.
 *
 * This function takes a CellChargeMap and draws the corresponding charges 
 * on a pad. It calculates the boundary points of each cell, creates a 
 * polygon line for each cell, sets the fill color based on the charge value,
 * and then draws the polygons on the pad.
 *
 * @param ccmap A map of cell charges.
 * @param option Drawing option.
 * @param FI Fill index.
 * @return 0 on success.
 * This comment was generated by meta-llama/Llama-3.3-70B-Instruct:None at temperature 0.01.
*/ 
int ToyEventDisplay::draw_truthcells_charge(const WCP::CellChargeMap& ccmap, TString option, int FI)
{
  pad.cd();

  //  g2 = new TGraph();
  //int i=0;

  Double_t x[100],y[100];

  for (auto it = ccmap.begin();it!=ccmap.end(); it++){
    //WCP::Point p = it->first->center();
    
    WCP::PointVector boundary = it->first->boundary();
    int n = 0;
    for (int i=0;i!=boundary.size();i++){
      x[n] = boundary[i].z/units::m;
      y[n] = boundary[i].y/units::m;
      n++;
    }
    x[n] = x[0];
    y[n] = y[0];
    n++;
    g3 = new TPolyLine(n,x,y);

    float charge = it->second;
    int color = (charge - charge_min)/(charge_max-charge_min)*254;
    if (color <0) color = 0;
    if (color>254) color =254;
    

    
    color += FI;
    g3->Draw(option);
    g3->SetFillColor(color);
    g3->SetLineColor(2);
    g3->SetLineWidth(1.5);
    g3->Draw("fsame");
    
  }
  
  return 0;
}


/**
 * @brief Draws wires with their corresponding charges on a display.
 *
 * This function takes a WireChargeMap, an option string, and an integer FI as input,
 * and draws the wires with their respective charges on a display.
 *
 * @param wcmap A map containing wire-charge pairs.
 * @param option A string specifying drawing options.
 * @param FI An integer representing a fill index.
 * @return An integer indicating success or failure.
 * This comment was generated by meta-llama/Llama-3.3-70B-Instruct:None at temperature 0.01.
*/ 
int ToyEventDisplay::draw_wires_charge(const WCP::WireChargeMap& wcmap, TString option, int FI)
{
  pad.cd();
  Double_t x[100],y[100];

  for (auto it = wcmap.begin();it!=wcmap.end(); it++){

    const WCP::GeomWire *wire = it->first;
    float charge = it->second;
    
    float pitch = gds->pitch(wire->plane());
    float angle = gds->angle(wire->plane());
    
    
    x[0] = wire->point1().z/units::m - pitch/2./units::m/std::cos(angle/units::radian); 
    y[0] = wire->point1().y/units::m;
    x[1] = wire->point2().z/units::m - pitch/2./units::m/std::cos(angle/units::radian);
    y[1] = wire->point2().y/units::m;
    x[3] = wire->point1().z/units::m + pitch/2./units::m/std::cos(angle/units::radian);
    y[3] = wire->point1().y/units::m;
    x[2] = wire->point2().z/units::m + pitch/2./units::m/std::cos(angle/units::radian);
    y[2] = wire->point2().y/units::m;
    x[4] = x[0];
    y[4] = y[0];
    g3 = new TPolyLine(5,x,y);

    int color = (charge - charge_min)/(charge_max-charge_min)*254;
    if (color <0) color = 0;
    if (color>254) color =254;
    color += FI;
    g3->Draw(option);
    g3->SetLineColor(1);
    g3->SetLineWidth(1);
    g3->SetFillColor(color);
  
  }
  return 0;
}



