/**
 * @brief Draws reconstructed cells on a display.
 *
 * This function takes a selection of geometric cells, a toy matrix,
 * an option string, and a color integer as input. It then draws the 
 * selected cells on a graph, applying a threshold filter based on 
 * the charge values obtained from the toy matrix.
 *
 * @param cellall A selection of geometric cells to draw.
 * @param toymatrix A toy matrix used to calculate charge values.
 * @param option An option string controlling the drawing behavior.
 * @param color An integer representing the color to use for drawing.
 *
 * @return An integer indicating the result of the operation.
 * This comment was generated by meta-llama/Llama-3.3-70B-Instruct:None at temperature 0.01.
*/ 
int ToyEventDisplay::draw_reconcells(const WCP::GeomCellSelection& cellall, WCP2dToy::ToyMatrix *toymatrix ,TString option, int color){
  
  pad.cd();
  g2 = new TGraph();
  int ncount = 0;
  for (int i=0;i!=cellall.size();i++){
    WCP::MergeGeomCell *mcell = (WCP::MergeGeomCell*)cellall[i];
    if (toymatrix->Get_Cell_Charge(mcell)>recon_threshold){
      WCP::GeomCellSelection acell = mcell->get_allcell();
      for (int j=0;j!=acell.size();j++){
	g2->SetPoint(ncount,acell[j]->center().z/units::m,acell[j]->center().y/units::m);
	ncount ++;
      }
    }
  }
  
  g2->SetMarkerColor(color);
  g2->SetMarkerSize(0.8);
  g2->Draw(option);
  g2->SetMarkerStyle(21);
  
  return 0;

  
}
